class Signaling:
    """Workpeg's half of a call, which WebRTC leaves to the application:
    finding the other person and passing offers, answers and candidates
    between the two pages. A page has one, :data:`signaling`.

    Each member asks the Workpeg API's calls routes for the business in the
    page's address (``/b/<business>/...``), with the person's own session
    and the page's peg: ``people/``, ``people/me/`` and ``signals/``, and
    nothing else. The API stamps who sent each signal and lets only the two
    people in a call read it; a signal lives two minutes. The peg needs
    the ``calls`` scope, declared in its manifest and granted by Workpeg.
    A page whose session has expired is refreshed first, as every
    ``workpeg`` call is. All four are awaited, with positional arguments.

    A refusal's ``failure.problem`` is the API's: ``"call-taken"`` (a claim
    another tab won), ``"signal-rate"``, ``"no-such-call"``,
    ``"no-such-person"``, ``"bad-query"``, ``"not-callable"``,
    ``"not-staff"``, ``"scope-not-declared"``, ``"not-a-peg-page"``, or
    ``"no-business"`` on a page under no business. None of these is asked
    again: only a 401, or a 403 that names no reason, refreshes the session
    and asks once more.
    """

    def __init__(self):
        _compiled("Signaling", "Use signaling, the page's one.")

    async def me(self) -> dict:
        """Who is signed in: ``{"id", "name", "handle"}``."""
        _compiled("Signaling.me")

    async def people(self, q, /) -> list:
        """Up to 20 people of this business who can be called, as
        ``{"id", "name", "handle", "open"}``. ``q`` is a search of 1 to 64
        characters by name or handle; ``""`` lists the first 20. ``open``
        is True when that person's page read its signals in the last 90
        seconds."""
        _compiled("Signaling.people")

    async def send(self, to, kind, data, call=None, claim=None, /) -> dict:
        """Send ``kind`` (1 to 32 of a to z and ``-``, not ``"taken"``) and
        ``data`` (JSON of at most 64 KiB) to the person whose id is ``to``.
        Without ``call`` this starts a call and the API mints its id; with
        it, the signal belongs to that call. ``claim=True`` claims the call
        (accept, decline, busy): the first claim wins, a later one fails
        with ``"call-taken"``, and the claimer's other tabs get ``"taken"``.
        Resolves ``{"id", "call", "recipient_open"}``."""
        _compiled("Signaling.send")

    async def receive(self, after, /) -> list:
        """Up to 50 of my signals with an id above ``after``, oldest first:
        ``{"id", "call", "kind", "from", "from_person", "data", "age"}``.
        ``from`` and ``from_person`` are the API's, never the sender's
        word; ``age`` is in seconds. Keep the last ``id`` and pass it next
        time."""
        _compiled("Signaling.receive")


